// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { c = new RoundFactory(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.prank(address(this));
        c.initialize();
        c.programOperators(alice);
        address dummyRound = address(0x2222);
        address dummyAllo = address(0x3333);
        vm.prank(address(this));
        c.updateRoundImplementation(payable(dummyRound));
        vm.prank(address(this));
        c.updateAlloSettings(dummyAllo);
        address newImpl = address(0x4444);
        c.roundImplementation();
        vm.prank(address(this));
        c.updateRoundImplementation(payable(newImpl));
        bool ok;
        address oldImpl = c.roundImplementation();
        vm.prank(address(this));
        try c.updateRoundImplementation(payable(newImpl)) { ok = true; } catch { ok = false; }
        assertTrue(ok == true);
    }
}
